def compose(*funcs):
    def composed(x):
        result = x
        for f in reversed(funcs):
            result = f(result)
        return result
    return composed

if __name__ == '__main__':
    double = lambda x: x * 2
    add_three = lambda x: x + 3
    pipeline = compose(double, add_three)
    assert pipeline(5) == 16
    print("✔ Function compose verified!")

import functools
import time

def timing_decorator(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = fn(*args, **kwargs)
        elapsed = time.perf_counter() - start
        print(f"[PERF] {fn.__name__} executed in {elapsed*1000:.3f}ms")
        return result
    return wrapper

@timing_decorator
def compute_sum(n):
    return sum(range(n))

