def chunked(iterable, size):
    chunk = []
    for item in iterable:
        chunk.append(item)
        if len(chunk) == size:
            yield chunk
            chunk = []
    if chunk:
        yield chunk

if __name__ == '__main__':
    data = [1, 2, 3, 4, 5, 6, 7]
    chunks = list(chunked(data, 3))
    assert chunks == [[1, 2, 3], [4, 5, 6], [7]]
    print("✔ Chunked generator verified!")

