import os

class TemporaryEnv:
    def __init__(self, key, value):
        self.key = key
        self.value = value
        self.old_val = None

    def __enter__(self):
        self.old_val = os.environ.get(self.key)
        os.environ[self.key] = self.value
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.old_val is None:
            os.environ.pop(self.key, None)
        else:
            os.environ[self.key] = self.old_val

if __name__ == '__main__':
    with TemporaryEnv('TRAK_TEST', '123'):
        assert os.environ['TRAK_TEST'] == '123'
    assert 'TRAK_TEST' not in os.environ
    print("✔ TemporaryEnv context manager passed!")

