import json

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

class PointEncoder(json.JSONEncoder):
    def default(self, o):
        if isinstance(o, Point):
            return {'x': o.x, 'y': o.y}
        return super().default(o)

if __name__ == '__main__':
    p = Point(10, 20)
    out = json.dumps(p, cls=PointEncoder)
    assert out == '{"x": 10, "y": 20}'
    print("✔ Custom JSONEncoder verified!")
